class.description:
A [PerformanceBudget] is a list of [PerformanceBudgetRule]s. Create it in the Inspector and save it as a [code].tres[/code] file, then check a run with [method PerformanceRecorder.check_budget], or pass it on the command line with [code]--performance-budget <file>[/code] (or [member ProjectSettings.debug/performance_recording/budget]) to make an automated run exit with code [code]1[/code] when a rule fails.
[codeblocks]
[gdscript]
var budget = PerformanceBudget.new()
var rule = PerformanceBudgetRule.new()
rule.column = "frame_time"
rule.statistic = PerformanceBudgetRule.STATISTIC_PERCENTILE
rule.percentile = 99.0
rule.limit = 33333.0 # 30 FPS
budget.add_rule(rule)

var result = PerformanceRecorder.check_budget(budget)
print(result.to_text())
[/gdscript]
[csharp]
var budget = new PerformanceBudget();
budget.AddRule(new PerformanceBudgetRule
{
	Column = "frame_time",
	Statistic = PerformanceBudgetRule.StatisticEnum.Percentile,
	Percentile = 99.0,
	Limit = 33333.0, // 30 FPS
});

var result = PerformanceRecorder.CheckBudget(budget);
GD.Print(result.ToText());
[/csharp]
[/codeblocks]
